#include "PluginProcessor.h"
bool PocketProcessor::startInputCapture(juce::String& error){if(getTotalNumInputChannels()==0){error="Enable the plugin audio input in the host or standalone Audio/MIDI settings first.";return false;}if(inputCapturing.load())return true;double sr;{const juce::ScopedLock lock(getCallbackLock());sr=rate;}std::vector<float> next(size_t(sr*16),0);{const juce::ScopedLock lock(getCallbackLock());inputCapture.swap(next);captureWrite=0;captureRate=sr;inputCaptureFrames.store(0);inputCapturing.store(true);}return true;}
bool PocketProcessor::finishInputCapture(juce::String& error){pocket::Sample captured;{const juce::ScopedLock lock(getCallbackLock());inputCapturing.store(false);if(captureWrite<1){error="No input audio was captured.";return false;}captured.rate=captureRate;captured.frames.assign(inputCapture.begin(),inputCapture.begin()+captureWrite);}float peak=0;for(float value:captured.frames)peak=std::max(peak,std::abs(value));if(peak<.000001f){error="Input was silent. Select/unmute an input device or enable sidechain routing in your DAW.";return false;}publishSamplePreview(captured);const int frames=int(captured.frames.size());{const juce::ScopedLock lock(getCallbackLock());engine.swapSample(captured);sampleFrames.store(frames);}for(auto pair:{std::pair{"engine",3.f},{"tone",0.f},{"color",1.f},{"sampleRoot",60.f}}){auto* p=state.getParameter(pair.first);p->setValueNotifyingHost(p->convertTo0to1(pair.second));}setSelectedSound({});currentFactoryPreset.store(-1);currentUserPreset.store(-1);requestPanic(false);return true;}
